#[no_mangle]
pub extern "C" fn fill_view(x0: i32, y0: i32, w: i32, h: i32) -> i32 {
    if w <= 0 || h <= 0 || w > VIEW_W as i32 || h > VIEW_H as i32 {
        return 0;
    }
    unsafe {
        for j in 0..h {
            let y = y0 + j;
            for i in 0..w {
                let x = x0 + i;
                let t = get_tile(x, y);
                let wall = wall_at(x, y);
                let idx = (j * w + i) as usize;
                VIEW[idx] = t as u32 | ((wall as u32) << 8);
            }
        }
    }
    (w * h) as i32
}

