        "Mesa" => 13,
        "Ladrillo" => 14,
        "Palo" => 15,
        "Pico" => 16,
        "Hacha" => 17,
        "Espada" => 18,
        "Gel" => 19,
        "Venda" => 20,
        _ => 0,
    }
}

