:root {
  --ink: #0b0f20;
  --panel: rgba(13, 19, 39, 0.82);
  --panel-2: rgba(20, 29, 56, 0.92);
  --line: rgba(160, 196, 255, 0.18);
  --line-strong: rgba(160, 196, 255, 0.35);
  --cream: #f3eddb;
  --muted: #a9b5d0;
  --lime: #b9ef69;
  --lime-2: #83d34d;
  --gold: #ffd35c;
  --orange: #ff9b54;
  --red: #ff5c66;
  --blue: #78c8ff;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.5);
  --pixel: 3px;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  overflow: hidden;
  background: #0a0e1d;
  color: var(--cream);
  font-family: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
button { font: inherit; color: inherit; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border: 1px solid rgba(220, 235, 255, 0.3);
  border-bottom-color: rgba(220, 235, 255, 0.12);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  color: #f8f5e8;
  font: 700 10px/1 "Courier New", monospace;
  letter-spacing: 0.02em;
}
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0a0e1d;
  cursor: crosshair;
}
#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 45%, transparent 48%, rgba(4, 7, 16, 0.28) 100%),
    linear-gradient(to bottom, rgba(3, 5, 12, 0.18), transparent 18%, transparent 78%, rgba(3, 5, 12, 0.3));
  z-index: 2;
}

/* ------------------------------------------------------------------ HUD */
#hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
#hud button { pointer-events: auto; }
.panel {
  background: linear-gradient(180deg, rgba(24, 34, 62, 0.88), rgba(10, 16, 34, 0.84));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 8px 22px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(8px);
}
.panel-label {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: #c7d4ef;
  font: 700 9px/1.2 "Courier New", monospace;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}
.top-left { position: absolute; top: 18px; left: 18px; display: grid; gap: 10px; width: 238px; }
.health-panel { border-radius: 9px; padding: 10px 12px 11px; }
.hearts { display: flex; gap: 4px; margin-top: 7px; height: 17px; }
.heart {
  width: 15px;
  height: 14px;
  position: relative;
  display: inline-block;
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.25));
  transition: opacity 0.15s, transform 0.15s;
}
.heart::before, .heart::after {
  content: "";
  position: absolute;
  top: 0;
  width: 8px;
  height: 12px;
  border-radius: 7px 7px 2px 2px;
  background: linear-gradient(180deg, #ff8a83, #f14954 55%, #c92b3d);
}
.heart::before { left: 1px; transform: rotate(-45deg); transform-origin: 50% 100%; }
.heart::after { right: 1px; transform: rotate(45deg); transform-origin: 50% 100%; }
.heart.empty { opacity: 0.22; filter: grayscale(1); }
.heart.beat { transform: scale(1.22); }
.quest-panel { border-radius: 9px; padding: 10px 12px 11px; }
#quest-list { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 5px; }
#quest-list li {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #d6dceb;
  font: 600 11px/1.25 "Trebuchet MS", sans-serif;
  transition: color 0.2s;
}
#quest-list li .check {
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  border: 1px solid rgba(190, 210, 245, 0.4);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.04);
  position: relative;
}
#quest-list li.done { color: #8f9cb8; text-decoration: line-through; text-decoration-color: rgba(185, 239, 105, 0.45); }
#quest-list li.done .check { background: var(--lime); border-color: var(--lime); box-shadow: 0 0 12px rgba(185, 239, 105, 0.35); }
#quest-list li.done .check::after {
  content: "";
  position: absolute; left: 3px; top: 1px; width: 4px; height: 7px;
  border: solid #1b2b11; border-width: 0 2px 2px 0; transform: rotate(42deg);
