    }

    const horizon = (wasm.surface_at_export(Math.floor(cam.x)) - cam.y) * TS + H / 2;
    const isDay = t > 0.23 && t < 0.79;
    const p = isDay ? (t - 0.23) / 0.56 : (((t + 0.21) % 1) / 0.44);
    const cx = W * (0.08 + 0.84 * p);
