    const radius = TS * (isDay ? 1.1 : 0.9);
    const glow = ctx.createRadialGradient(cx, cy, radius * 0.4, cx, cy, radius * 5.5);
    if (isDay) {
      glow.addColorStop(0, 'rgba(255,240,180,.5)');
