    drawRidge(horizon - 14, H * 0.20, `rgb(${far.join(',')})`, 0.16, 0.4, 1.0, 24);
    drawRidge(horizon - 3, H * 0.14, `rgb(${mid.join(',')})`, 0.32, 2.2, 1.45, 18);
