      [GRASS]: '#6bc24a', [DIRT]: '#81522f', [STONE]: '#8d97a6', [WOOD]: '#956132',
      [LEAVES]: '#4d9b43', [PLANK]: '#c08a50', [TORCH]: '#ffab3f', [COAL]: '#32343c',
      [IRON]: '#d9a17b', [GOLD]: '#f5cf5b', [SAND]: '#e4cd8a', [FLOWER]: '#ff7d5e',
      [TABLE]: '#c08a50', [BRICK]: '#9aa0aa'
    }[tile] || '#9a8a72';
